#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBrilliantCore: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = BrilliantCore

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> BrilliantCore {
        return BrilliantCore(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: BrilliantCore) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BrilliantCore {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: BrilliantCore, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}




#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeBrilliantCore_lift(_ pointer: UnsafeMutableRawPointer) throws -> BrilliantCore {
    return try FfiConverterTypeBrilliantCore.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeBrilliantCore_lower(_ value: BrilliantCore) -> UnsafeMutableRawPointer {
    return FfiConverterTypeBrilliantCore.lower(value)
}




/**
 * The migrated BrowserSim protocol state machine. One per shell
 * `BrowserSimTransport`.
 */
public protocol BrowserSimCoreProtocol : AnyObject {
    
    /**
     * Abort the in-flight `capture_video` — the explicit-abort design (the
     * Stage-0 finding: a dropped future's `Drop` cannot run the async
     * abort+drain). Sends `capture_video_abort`, then a bounded drain: if the
     * browser does not emit the partial `video_result` within
     * `VIDEO_DRAIN_TIMEOUT_MS`, force-resolves the pending op so the in-flight
     * `capture_video` returns rather than waiting the full op timeout.
     *
     * **F18 (iteration-3 root cause + fix):** the original implementation
     * slept `VIDEO_DRAIN_TIMEOUT_MS` UNCONDITIONALLY and only checked at
     * the end. If `video_result` arrived during the sleep, it landed in
     * `complete_pending` which removed the sender and delivered the value
     * — the post-sleep `remove` was a no-op (sender already gone). Normal
     * case worked fine.
     *
     * But if `video_result` arrived AFTER the sleep ended (e.g. an 8MB+
     * frame traversing OkHttp on a slow network — observed 6s delivery
     * delay in iteration-3 dogfood, frame arrived at T+10.083s while
     * sleep ended at T+10.000s), abort had already force-resolved
     * `pending` with `{"type":"aborted"}`. `complete_pending` then ran
     * for the late `video_result`, found no sender, and logged the
     * well-named "duplicate or post-timeout response — ignoring" before
     * dropping it on the floor.
     *
     * Fix: replace the unconditional sleep with a poll loop that exits
     * early when the pending sender is removed (signal that
     * `complete_pending` consumed the `video_result` and delivered it).
     * Bump the max wait so large frames have headroom.
     */
    func abortCaptureVideo() async 
    
    /**
     * The current activity phase — the subscriber seed, since the event
     * stream carries no replay. Twin of `RealMetaCore::camera_stream_state`.
     */
    func cameraStreamState()  -> CameraStreamState
    
    /**
     * Cancel the currently-speaking utterance — fire-and-forget.
     */
    func cancelSpeak() 
    
    /**
     * Capture a still photo through the browser surrogate.
     */
    func capturePhoto(resolution: Resolution, format: PhotoFormat, dedicatedCapture: Bool) async  -> CapturePhotoResult
    
    /**
     * Capture a video clip through the browser surrogate.
     */
    func captureVideo(maxDurationSeconds: Int32?, includeAudio: Bool, format: VideoFormat) async  -> CaptureVideoResult
    
    /**
     * Open the simulator session. `mcp_install_id` is the shell's MCP
     * `/whoami` probe result (the probe stays shell-side — the core does no
     * network). Returns `None` on success, `Some(ConnectError)` on failure.
     */
    func connect(mcpInstallId: String?) async  -> ConnectError?
    
    /**
     * The currently-bound session URL, if any. The shell mirrors this for
     * its `currentSessionUrl()` getter.
     */
    func currentSessionUrl()  -> String?
    
    /**
     * The session's current device model id (identity dial,
     * device-capability-model.md) — `None` until the handshake delivers it.
     * Backs the shell's `GlassesTransport.currentDeviceModelId()`.
     */
    func deviceModelId()  -> String?
    
    /**
     * The session's current device VENDOR wire id ("meta", …) — the vendor
     * half of the identity dial, catalog-resolved by the backend and captured
     * from the same frames as `device_model_id`. `None` until a vendor-aware
     * backend delivers it. Backs the shell's
     * `GlassesTransport.currentVendorId()`.
     */
    func deviceVendor()  -> String?
    
    /**
     * End the session at the customer's request.
     */
    func disconnect() 
    
    /**
     * Play a short non-speech earcon — fire-and-forget.
     */
    func earcon(sound: EarconSound, volume: Float) 
    
    /**
     * True while the surrogate's camera stream is paused (capture-button
     * tap on the sim page or a headless `hardware_button` inject). Mirrors
     * `RealMetaCore::is_camera_paused` — the shells' shared paused gate
     * (`DefaultCameraClient` / `CameraClient.swift`) reads this so a paused
     * sim capture fails with the SAME `CaptureError.StreamPaused` a wearer's
     * temple tap produces on real glasses.
     */
    func isCameraPaused()  -> Bool
    
    /**
     * An inbound binary frame — the payload of the preceding meta frame.
     */
    func onBinary(bytes: Data) 
    
    /**
     * The socket closed (`code` is the WebSocket close code). A non-clean
     * closure (anything but 1000) drives the reconnect loop.
     */
    func onClosed(code: Int32, reason: String) 
    
    /**
     * The socket failed (a structured `code` + `message` from the shell).
     * Mirrors Android's `onFailure`: resolve a pending open-await *and* drive
     * the reconnect loop — a failed initial `connect()` still retries in the
     * background, exactly as the shells do today.
     */
    func onFailure(code: String, message: String) 
    
    /**
     * The socket opened — send the `session_init` handshake and unblock the
     * `connect()` open-outcome await.
     */
    func onOpen() 
    
    /**
     * An inbound text frame — parsed and routed to the per-type handler.
     */
    func onText(text: String) 
    
    /**
     * Record a discrete audio clip — races the browser surrogate's
     * `audio_result` against the next FINAL transcript, so an MCP-injected
     * transcript can satisfy a pending `recordDiscrete` (F-R5-03).
     */
    func recordAudio(maxDurationSeconds: Int32?, silenceTimeoutSeconds: Double?, quality: AudioQuality) async  -> RecordAudioResult
    
    /**
     * Buffer-or-send an outbound runtime-event frame. Called by the shell's
     * runtime-event forwarder; frames enqueued before the session is ready are
     * held (bounded, drop-oldest) and drained on `session_init` /
     * `session_attached`.
     */
    func sendOutbound(payloadJson: String) 
    
    /**
     * Phase 3 / Track 2 audio-OUT — push a chunk of TTS PCM to the
     * simulator browser as a paired JSON-metadata + binary-frame
     * envelope (mirrors the audio_chunk IN convention; see
     * `handle_audio_chunk_meta` + `handle_binary` at line 1223+).
     *
     * Wire shape:
     * 1. JSON `{ "type": "tts_audio_chunk", "timestamp_ms": <now>,
     * "sample_rate": <hz> }` — the browser pairs this with the
     * next binary frame on the same WS connection.
     * 2. Binary frame — raw i16 LE PCM bytes, mono, at `sample_rate`.
     *
     * The hub's F1 binary relay (backend/src/lib/ws-hub.ts) forwards
     * both to the browser leg preserving FIFO order — the pairing
     * invariant the receiver depends on.
     *
     * Called from the shell's `SpeakAudioSink` impl as chunks stream
     * off A4's TtsStream. v1 OpenAI TTS emits 24 kHz mono i16 LE; the
     * shell passes `sample_rate=24000` to match.
     *
     * Browser playback (E3) lives in SimulatorClient.tsx — see the
     * `tts_audio_chunk` JSON handler + the AudioBuffer queue.
     */
    func sendOutgoingAudioChunk(sampleRate: Int32, pcmBytes: Data) 
    
    /**
     * Rebind the session URL at runtime (the iOS `setSessionUrl` analogue —
     * also surfaced on the Android shell). Used by `DebugClient` to point a
     * running transport at a freshly-created simulator session without
     * reconstructing the core. Takes effect on the next `connect()` /
     * reconnect attempt.
     */
    func setSessionUrl(url: String?) 
    
    /**
     * Tear the transport down — no reconnect, no further events.
     */
    func shutdown() 
    
    /**
     * Speak text through the browser surrogate's TTS.
     */
    func speak(text: String, voice: String?, rate: Double, pitch: Double, volume: Double, waitForCompletion: Bool) async  -> SpeakResult
    
    /**
     * Start delivering audio chunks to `sink` and send `stream_start`.
     */
    func startAudioStream(chunkMillis: Int32, sampleRate: Int32, sink: AudioChunkSink)  -> String
    
    /**
     * Register a transcription sink (multi-subscriber). Returns the stream id
     * the shell passes back to [`stop_transcription_stream`] to unregister.
     */
    func startTranscriptionStream(language: String, partial: Bool, sink: TranscriptSink)  -> String
    
    /**
     * Start delivering video frames to `sink` and send `stream_start`. Returns
     * the stream id the shell passes back to [`stop_video_stream`].
     */
    func startVideoStream(frameRate: Int32, resolution: Resolution, sink: VideoFrameSink)  -> String
    
    func stopAudioStream(streamId: String) 
    
    func stopTranscriptionStream(streamId: String) 
    
    func stopVideoStream(streamId: String) 
    
}

