#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeRealMetaCore: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = RealMetaCore

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> RealMetaCore {
        return RealMetaCore(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: RealMetaCore) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RealMetaCore {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: RealMetaCore, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}




#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeRealMetaCore_lift(_ pointer: UnsafeMutableRawPointer) throws -> RealMetaCore {
    return try FfiConverterTypeRealMetaCore.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeRealMetaCore_lower(_ value: RealMetaCore) -> UnsafeMutableRawPointer {
    return FfiConverterTypeRealMetaCore.lower(value)
}




public protocol RealtimeVoiceCoreProtocol : AnyObject {
    
    func appendHistory(turn: RealtimeTurn) 
    
    /**
     * The shell's summarize / custom-compact attempt FAILED — clear the
     * in-flight compaction so the next trigger retries (a single failure
     * must not wedge compaction for the rest of the session).
     */
    func cancelCompaction() 
    
    func cancelSpeak() 
    
    func clearHistory() 
    
    /**
     * Wake: open the WS, send `session.update`, await `session.updated`, then
     * memory/replay/glasses-state + `SessionStarted`. `None` on success,
     * `Some(error)` on failure. The shell's bridge opens the socket with the
     * gateway auth headers; the core owns the protocol sequence.
     */
    func connect(replay: Bool) async  -> String?
    
    func conversationHistory(limit: UInt32)  -> [RealtimeTurn]
    
    /**
     * Sleep: close the WS. History is preserved for the next wake; protocol-
     * specific session state that must NOT survive a sleep (Gemini's
     * resumption handle) is dropped so the next wake is a fresh session.
     */
    func disconnect() 
    
    func greet(prompt: String?) 
    
    func includeImage(imageUrl: String, prompt: String?) 
    
    func injectSystemContext(text: String) 
    
    func injectUserTurn(text: String) 
    
    /**
     * The WS closed. A close arriving before `on_open` is an open failure too —
     * the server hung up on the handshake — so it routes through `on_failure`.
     */
    func onClosed() 
    
    /**
     * The WS failed (the shell's bridge `onFailure`) — resolve a pending open
     * AND kick the reconnect supervisor.
     *
     * `code` is a machine-readable token the app can branch on
     * (`project_quota_exceeded`, `invalid_credential`, `http_429`, …); `message`
     * is human text. Both come from the shell, which is the only layer that can
     * see the transport's failure detail.
     *
     * Resolving the pending open is the load-bearing half. This used to return
     * early unless `connected` was already true — but `connected` only flips
     * AFTER a successful open, so during the connect window this was a no-op and
     * the oneshot was never resolved. Every open failure therefore had exactly
     * one observable outcome: the full 10 s `OPEN_TIMEOUT_MS` followed by
     * "realtime WebSocket open timed out", whether the cause was a quota
     * rejection, a bad credential, DNS or TLS. A gateway 429 that arrived in
     * milliseconds read as a hung network, which cost two debugging sessions
     * (2026-07-17, 2026-08-15) before anyone thought to read the server log.
     */
    func onFailure(code: String, message: String) 
    
    /**
     * A mic chunk from the audio device — encode it to the protocol's audio
     * frame (may be empty: Gemini drops pre-ready chunks).
     */
    func onMicAudio(sampleRate: Int32, pcm: Data) 
    
    /**
     * The WS opened (the shell's bridge `onOpen`) — unblock `connect`.
     */
    func onOpen() 
    
    /**
     * An inbound WS text frame (the shell's WS reader calls this synchronously,
     * preserving order). Mutate under the lock, drop, then perform effects.
     */
    func onText(text: String) 
    
    func replaceHistory(turns: [RealtimeTurn]) 
    
    func say(text: String) 
    
    /**
     * Streaming video input (Gemini Live only, per-model gated). Non-video
     * sessions emit an `Error{kind: "video_input_unsupported"}` event instead
     * of silently dropping the frame.
     */
    func sendVideoFrame(frame: Data, mimeType: String) 
    
    /**
     * Turn outgoing-audio metering on or off.
     *
     * Off by default and free while off: no RMS is computed, no frames are
     * buffered, no events are emitted, and the activity watcher stays on its
     * slow tick. The shell flips this from its levels stream's subscriber
     * count, so the cost exists only while an app is actually drawing.
     *
     * Turning it off mid-speech emits nothing further — the subscriber has
     * gone, so there is nobody owed a closing zero.
     */
    func setAudioLevelsEnabled(enabled: Bool) 
    
    func setMemoryPreamble(preamble: String?) 
    
    func setModel(model: String) 
    
    func setReasoningEffort(effortWire: String) 
    
    func setVoice(voice: String) 
    
    /**
     * The shell finished summarizing (the `request_summary` callback) — apply it.
     */
    func submitCompacted(summaryText: String) 
    
    /**
     * The shell finished running a customer tool handler.
     */
    func submitToolResult(callId: String, name: String, output: String, isError: Bool, durationMs: Int64) 
    
    func updateInstructions(instructions: String) 
    
}

open class RealtimeVoiceCore:
