         * `None` when the agent is not speaking (e.g. thinking).
         */agentSpeakingElapsedMs: UInt32?) {
        self.durationMs = durationMs
        self.wordCount = wordCount
        self.isEcho = isEcho
        self.agentSpeakingElapsedMs = agentSpeakingElapsedMs
    }
}



