/**
 * Why a capture (`capturePhoto` / `captureVideo`) failed. Migrated 1:1 from the
 * hand-written `CaptureError`; the `PlatformError(Throwable)` variant is
 * redesigned to structured `code` + `message` per the § 3b error policy above.
 */

public enum CaptureError {
    
    case notConnected
    case permissionDenied
    case thermalCritical
    case hingesClosed
    case coexistenceBlocked
    /**
     * The user paused the camera with the glasses' capture button (temple tap),
     * so the live stream this capture needs is held, not flowing. The pause is a
     * deliberate hardware privacy gesture and there is NO app-callable resume
     * (verified against Meta DAT 0.8) — the user must tap the temple again. A
     * handler should surface a prompt like "Tap the right temple of your glasses
     * to resume the camera"; the capture succeeds on retry once frames resume.
     */
    case streamPaused
    /**
     * A user-facing toggle is gating this capture; `toggle` is the toggle key
     * (e.g. `camera_streaming_enabled`) so a handler can explain it.
     */
    case disabledByUser(toggle: String
    )
    /**
     * A native-origin capture failure — structured `code` + `message`.
     */
    case platformError(code: String, message: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCaptureError: FfiConverterRustBuffer {
    typealias SwiftType = CaptureError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CaptureError {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .notConnected
        
        case 2: return .permissionDenied
        
        case 3: return .thermalCritical
        
        case 4: return .hingesClosed
        
        case 5: return .coexistenceBlocked
        
        case 6: return .streamPaused
        
        case 7: return .disabledByUser(toggle: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .platformError(code: try FfiConverterString.read(from: &buf), message: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CaptureError, into buf: inout [UInt8]) {
        switch value {
        
        
        case .notConnected:
            writeInt(&buf, Int32(1))
        
        
        case .permissionDenied:
            writeInt(&buf, Int32(2))
        
        
        case .thermalCritical:
            writeInt(&buf, Int32(3))
        
        
        case .hingesClosed:
            writeInt(&buf, Int32(4))
        
        
        case .coexistenceBlocked:
            writeInt(&buf, Int32(5))
        
        
        case .streamPaused:
            writeInt(&buf, Int32(6))
        
        
        case let .disabledByUser(toggle):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(toggle, into: &buf)
            
        
        case let .platformError(code,message):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


