// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Events the runtime emits to the customer's observer (the FFI projection of the
 * internal `AssistantEventOut`; tool args cross as a JSON string).
 */

public enum RealtimeEvent {
    
    case userSpoke(transcript: String
    )
    case assistantSpoke(transcript: String
    )
    /**
     * The assistant started talking — the rising edge of audible speech.
     *
     * Distinct from `AssistantSpoke`, which carries the transcript and fires
     * when GENERATION finished. The model streams audio faster than realtime, so
     * `AssistantSpoke` routinely lands seconds before the speaker goes quiet;
     * anything that should track whether the assistant is currently talking —
     * a "speaking" indicator, a screen transition — belongs on this pair.
     */
    case assistantAudioStarted
    /**
     * The assistant stopped talking: its queued audio drained and the model
     * finished the turn (including any tool round trip inside it).
     *
     * Also fires immediately when playback is cut short by barge-in or
     * `cancelSpeak` — the audio did stop, and a consumer waiting on this edge
     * must not hang because the user interrupted.
     *
     * The drain is the core's estimate from the PCM it queued, not a report
     * from the speaker. On glasses the phone is the player and the Ray-Bans are
     * a Bluetooth sink, so the last ~100-200 ms of the hop is invisible to any
     * layer of this SDK. Treat it as "has finished, to within ~a quarter
     * second", which is what a UI transition needs and more than a `speak()`
     * completion ever promised.
     */
    case assistantAudioFinished
    /**
     * How loudly the assistant is speaking right now — RMS of the audio
     * currently audible, normalised 0...1 against full scale.
     *
     * Opt-in: nothing is computed or emitted until a consumer calls
     * `set_audio_levels_enabled(true)`, so an app that never asks pays nothing.
     *
     * Emitted at a fixed ~25 Hz **on the playback clock**, not when audio was
     * queued — the model streams faster than real time, so metering at enqueue
     * would run a visualiser ahead of the voice by the whole queue depth. Only
     * ever between `AssistantAudioStarted` and `AssistantAudioFinished`, with a
     * closing `0.0` when playback is cut short.
     */
    case assistantAudioLevel(level: Float
    )
    case toolCalled(name: String, argsJson: String, callId: String
    )
    case toolResult(callId: String, name: String, output: String, isError: Bool, durationMs: Int64
    )
    case error(kind: String, message: String
    )
    /**
     * First open completed — `session.update` accepted.
     */
    case sessionStarted(model: String, voice: String
    )
    /**
     * A reconnect cycle completed (the watchdog/failure-recovery path).
     */
    case reconnected(reason: String, downtimeMs: Int64
    )
    /**
     * The session ended (reconnect gave up, or a hard error).
     */
    case sessionEnded(reason: String, message: String?
    )
    /**
     * `sleepAfterSilence` reached — the conversation was genuinely idle (no user
     * speech, no active response, no assistant audio still playing) for the configured
     * timeout. The shell sleeps the assistant in response.
     */
    case silenceTimeout
}


