            FfiConverterString.write(name, into: &buf)
            FfiConverterString.write(output, into: &buf)
            FfiConverterBool.write(isError, into: &buf)
            FfiConverterInt64.write(durationMs, into: &buf)
            
        
        case let .error(kind,message):
