// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * BrowserSim-only UI guidance the connection page renders (`null` = clear).
 * `MeterExhausted` is dropped (decision 5 — it was iOS-only and never emitted).
 */

public enum SimulatorHint {
    
    case awaitingBrowser(sessionUrl: String
    )
    case browserMissing(reason: String
    )
    case browserReconnected
    case hardwareUnavailable(reason: String
    )
    case transportRetrying(attempt: Int32, nextDelayMs: Int64
    )
    case sessionExpired(reason: SessionExpireReason, detail: String?
    )
    case protocolMismatch(detail: String
    )
    case awaitingPair(code: String, expiresAtEpochMs: Int64
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSimulatorHint: FfiConverterRustBuffer {
    typealias SwiftType = SimulatorHint

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SimulatorHint {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .awaitingBrowser(sessionUrl: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .browserMissing(reason: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .browserReconnected
        
        case 4: return .hardwareUnavailable(reason: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .transportRetrying(attempt: try FfiConverterInt32.read(from: &buf), nextDelayMs: try FfiConverterInt64.read(from: &buf)
        )
        
        case 6: return .sessionExpired(reason: try FfiConverterTypeSessionExpireReason.read(from: &buf), detail: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 7: return .protocolMismatch(detail: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .awaitingPair(code: try FfiConverterString.read(from: &buf), expiresAtEpochMs: try FfiConverterInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SimulatorHint, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .awaitingBrowser(sessionUrl):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(sessionUrl, into: &buf)
            
        
        case let .browserMissing(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .browserReconnected:
            writeInt(&buf, Int32(3))
        
        
        case let .hardwareUnavailable(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .transportRetrying(attempt,nextDelayMs):
            writeInt(&buf, Int32(5))
            FfiConverterInt32.write(attempt, into: &buf)
            FfiConverterInt64.write(nextDelayMs, into: &buf)
            
        
        case let .sessionExpired(reason,detail):
            writeInt(&buf, Int32(6))
            FfiConverterTypeSessionExpireReason.write(reason, into: &buf)
            FfiConverterOptionString.write(detail, into: &buf)
            
        
        case let .protocolMismatch(detail):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .awaitingPair(code,expiresAtEpochMs):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(code, into: &buf)
            FfiConverterInt64.write(expiresAtEpochMs, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSimulatorHint_lift(_ buf: RustBuffer) throws -> SimulatorHint {
    return try FfiConverterTypeSimulatorHint.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSimulatorHint_lower(_ value: SimulatorHint) -> RustBuffer {
    return FfiConverterTypeSimulatorHint.lower(value)
}



