/**
 * The normalized stream-session vocabulary (R5) — adopts Android's richer
 * shape. iOS shell synthesizes `Streaming` from "first videoFrame arrived"
 * or equivalent SDK signal.
 */

public enum StreamState {
    
    case starting
    case started
    case streaming
    /**
     * DAT 0.8's SYSTEM-driven pause (`StreamImpl.pauseStreamFromLowerLayer`):
     * another app took the device session, the wearer folded the glasses, or a
     * system gesture opened another experience. There is NO app-callable
     * pause()/resume(). The channel is held but no frames flow — held ≠ live
     * (`stream_live` drops, so the next photo re-opens cold) and held ≠ dead:
     * Paused must NOT be treated as a disconnect; only `Closed` feeds recovery.
     */
    case paused
    case stopping
    case stopped
    case closed
}


