/**
 * `audioChunks` sink — as [`VideoFrameSink`]; `AudioChunk` stays native.
 */
public protocol AudioChunkSink : AnyObject {
    
    func onAudioChunk(timestampMs: Int64, sampleRate: Int32, data: Data) 
    
}

// Magic number for the Rust proxy to call using the same mechanism as every other method,
// to free the callback once it's dropped by Rust.
private let IDX_CALLBACK_FREE: Int32 = 0
// Callback return codes
private let UNIFFI_CALLBACK_SUCCESS: Int32 = 0
private let UNIFFI_CALLBACK_ERROR: Int32 = 1
private let UNIFFI_CALLBACK_UNEXPECTED_ERROR: Int32 = 2

// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceAudioChunkSink {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    static var vtable: UniffiVTableCallbackInterfaceAudioChunkSink = UniffiVTableCallbackInterfaceAudioChunkSink(
        onAudioChunk: { (
            uniffiHandle: UInt64,
            timestampMs: Int64,
            sampleRate: Int32,
            data: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceAudioChunkSink.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onAudioChunk(
                     timestampMs: try FfiConverterInt64.lift(timestampMs),
                     sampleRate: try FfiConverterInt32.lift(sampleRate),
                     data: try FfiConverterData.lift(data)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            let result = try? FfiConverterCallbackInterfaceAudioChunkSink.handleMap.remove(handle: uniffiHandle)
            if result == nil {
                print("Uniffi callback interface AudioChunkSink: handle missing in uniffiFree")
            }
        }
    )
}

private func uniffiCallbackInitAudioChunkSink() {
    uniffi_extentos_core_fn_init_callback_vtable_audiochunksink(&UniffiCallbackInterfaceAudioChunkSink.vtable)
}

