/**
 * Decoded device events, delivered to the shell.
 */
public protocol BrilliantObserver : AnyObject {
    
    func onStateChanged(state: LinkState) 
    
    func onPhoto(jpeg: Data) 
    
    /**
     * A completed capture, delivered when the device signals the end.
     */
    func onAudio(pcm: Data) 
    
    /**
     * One chunk of microphone audio, delivered AS IT ARRIVES.
     *
     * Separate from [`Self::on_audio`] on purpose: a voice app needs audio
     * while the person is still speaking, so waiting for the clip to finish
     * would make live transcription impossible. The same bytes reach both —
     * this one per chunk, that one accumulated at the end.
     */
    func onAudioChunk(pcm: Data) 
    
    func onTap() 
    
    func onClick(kind: ClickAction) 
    
    func onImu(data: Data) 
    
    /**
     * Focus should move one step, decided by the core from the orientation
     * stream (see [`super::OrientationFocus`]).
     *
     * Separate from [`Self::on_imu`] because the raw angles are a stream and
     * this is a DECISION: a continuous signal becoming discrete steps needs
     * hysteresis and a per-wearer baseline, and two shells writing that
     * independently would drift on the numbers. The shell moves focus and
     * repaints; it does not decide when.
     */
    func onFocusStep(step: FocusStep) 
    
    /**
     * Lua `print` output — diagnostics, and how the device reports Lua errors.
     *
     * Only delivered once the link is [`LinkState::Ready`]. During the
     * handshake the print channel carries acknowledgements, and forwarding
     * those as logs would bury the one line that matters if it fails.
     */
    func onDeviceLog(line: String) 
    
    /**
     * The bundle could not be installed or started. The link is still up, but
     * it is mute — worth surfacing rather than leaving an app waiting on a
     * `Ready` that will never arrive.
     */
    func onHandshakeFailed(reason: String) 
    
}



