/**
 * Diagnostics the core would otherwise send to `android.util.Log` / `os_log`.
 * The shell routes these to the platform logger (decision 1 of the 2a handoff).
 */
public protocol LogSink : AnyObject {
    
    func log(level: BridgeLogLevel, message: String) 
    
}



